CustomField.formula:
MOD(FLOOR(( IF (ISBLANK(Rebooked_Flight_Actual_Arrival_Date_Time__c), 0, IF (ISBLANK(Arrival_Date_Time__c), 0,  IF (ISBLANK(DATETIMEVALUE(
    /* Year Logic */
    MID(Arrival_Date_Time__c, 7,4) +'-'+
    /* Month Logic */
    MID(Arrival_Date_Time__c,
    FIND("/",Arrival_Date_Time__c) + 1,
    FIND("/",Arrival_Date_Time__c, FIND("/",Arrival_Date_Time__c) + 1) -
    FIND("/",Arrival_Date_Time__c) - 1
    )+'-'+
    /* Day Logic */
    LEFT(Arrival_Date_Time__c,
    FIND("/",Arrival_Date_Time__c) - 1) +' '+
    /* Time Logic */
    RIGHT(Arrival_Date_Time__c, 8)
    )),0, IF (ISBLANK(DATETIMEVALUE(
    /* Year Logic */
    MID(Arrival_Date_Time__c, 7,4) +'-'+
    /* Month Logic */
    MID(Arrival_Date_Time__c,
    FIND("/",Arrival_Date_Time__c) + 1,
    FIND("/",Arrival_Date_Time__c, FIND("/",Arrival_Date_Time__c) + 1) -
    FIND("/",Arrival_Date_Time__c) - 1
    )+'-'+
    /* Day Logic */
    LEFT(Arrival_Date_Time__c,
    FIND("/",Arrival_Date_Time__c) - 1) +' '+
    /* Time Logic */
    RIGHT(Arrival_Date_Time__c, 8)
    )),0, (Rebooked_Flight_Actual_Arrival_Date_Time__c - DATETIMEVALUE(
    /* Year Logic */
    MID(Arrival_Date_Time__c, 7,4) +'-'+
    /* Month Logic */
    MID(Arrival_Date_Time__c,
    FIND("/",Arrival_Date_Time__c) + 1,
    FIND("/",Arrival_Date_Time__c, FIND("/",Arrival_Date_Time__c) + 1) -
    FIND("/",Arrival_Date_Time__c) - 1
    )+'-'+
    /* Day Logic */
    LEFT(Arrival_Date_Time__c,
    FIND("/",Arrival_Date_Time__c) - 1) +' '+
    /* Time Logic */
    RIGHT(Arrival_Date_Time__c, 8)
    ))))) )  )*1440),60)
